package com.myassist.assistant.ui;
import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.myassist.assistant.MyAssistApp;import com.myassist.assistant.model.Models;import com.myassist.assistant.network.*;import org.json.*;import java.util.*;
public class JobsActivity extends AppCompatActivity{LinearLayout list;TextView error;int tab=0;JSONObject data;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_jobs);list=findViewById(R.id.list);error=findViewById(R.id.tvError);findViewById(R.id.btnAvailable).setOnClickListener(v->{tab=0;render();});findViewById(R.id.btnActive).setOnClickListener(v->{tab=1;render();});findViewById(R.id.btnCompleted).setOnClickListener(v->{tab=2;render();});load();}protected void onResume(){super.onResume();load();}void load(){ApiService.run(ApiService.get("api/v1/assistant/jobs"),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject o){data=o;runOnUiThread(()->render());}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});}void render(){if(data==null)return;String key=tab==0?"available":tab==1?"active":"completed";JSONArray a=data.optJSONArray(key);list.removeAllViews();if(a==null||a.length()==0){TextView v=new TextView(this);v.setText("No jobs");list.addView(v);return;}for(int i=0;i<a.length();i++){Models.ServiceRequest r=Models.ServiceRequest.fromJson(a.optJSONObject(i));TextView v=new TextView(this);v.setText("#"+r.id+"  "+r.serviceType+"\n"+r.description+"\n"+r.status);v.setTextSize(16);v.setPadding(20,20,20,20);v.setOnClickListener(x->startActivity(new Intent(this,JobDetailsActivity.class).putExtra("request_id",r.id)));list.addView(v);}}} 